struct perf_event_attr attr = {
    .type = PERF_TYPE_HARDWARE,
    .config = PERF_COUNT_HW_INSTRUCTIONS,
    .size = sizeof(attr),
    .disabled = 1, // Start measurement disabled
};

// Parameters for perf_event_open
pid_t target_pid = 0;   // Monitor current thread
int cpu = -1;           // Any CPU
int group_fd = -1;      // No grouping
unsigned long flags = 0;

int fd = syscall(__NR_perf_event_open,
                 &attr, target_pid, cpu,
                 group_fd, flags);

// If successful, fd > 0.
// Use ioctl(fd, PERF_EVENT_IOC_ENABLE, 0) to start.
// Use read(fd, &count, sizeof(count)) to retrieve data.
